WITH wanted(signature) AS (VALUES ('public.event_guest_payment_choose(uuid,text,integer,integer,uuid)'),('public.event_guest_payment_options(uuid)'),('public.event_host_allocate(uuid,uuid,uuid,uuid,integer,timestamp with time zone,integer,uuid)'),('public.event_host_claim(text,uuid)'),('public.event_host_claim_preview(text)'),('public.event_host_get(uuid)'),('public.event_host_guest_save(uuid,uuid,integer,uuid,text,integer,text)'),('public.event_host_list(uuid,uuid)'),('public.event_host_receipt(uuid)'),('public.event_host_release(uuid,integer,uuid)'),('public.event_host_request_cancel(uuid,text)'),('public.event_payment_policy_configure(uuid,uuid,integer,uuid,boolean,boolean,timestamp with time zone)'),('public.event_payment_policy_save(uuid,uuid,integer,uuid,boolean,boolean)'),('public.event_payment_request(uuid,text,jsonb,boolean)'),('public.table_hold_create(uuid,uuid,integer,integer,uuid)'),('public.table_hold_release(uuid)'),('public.table_hold_status(uuid,uuid)'),('public.table_identity_get(uuid,uuid)'),('public.table_identity_receipt(uuid,uuid,uuid)'),('public.table_identity_save(uuid,uuid,integer,uuid,jsonb)'),('public.table_inventory_configure(uuid,uuid,integer,uuid,jsonb)'),('public.table_inventory_configure_receipt(uuid,uuid,uuid)'),('zoi.event_host_cancelled(uuid,uuid,text)'),('zoi.event_host_valid(zoi.event_host_allocations)'),('zoi.event_payment_operator_current(uuid,uuid)'),('zoi.suite_current_session()'),('zoi.suite_lock_session()'),('zoi.table_inventory_actor()'),('zoi.table_inventory_operator(uuid,uuid)')) SELECT jsonb_build_object('checked_at',clock_timestamp(),'functions',(select jsonb_agg(jsonb_build_object('signature',w.signature,'definition',pg_get_functiondef(p.oid),'owner',pg_get_userbyid(p.proowner),'security_definer',p.prosecdef,'search_path',p.proconfig,'acl',p.proacl::text,'anon_execute',has_function_privilege('anon',p.oid,'EXECUTE'),'authenticated_execute',has_function_privilege('authenticated',p.oid,'EXECUTE'),'service_execute',has_function_privilege('service_role',p.oid,'EXECUTE')) order by w.signature) from wanted w join pg_proc p on p.oid=to_regprocedure(w.signature)),'migration',(select jsonb_agg(jsonb_build_object('name',name,'version',version)) from supabase_migrations.schema_migrations where name='event_table_current_session'))